function parseSemver(v) {
  if (typeof v !== 'string') {
    throw new TypeError('Version must be a string');
  }

  // Format: MAJOR.MINOR.PATCH, optionally followed by -PRERELEASE and/or +BUILD
  // MAJOR, MINOR and PATCH are non-negative integers without leading zeros.
  // PRERELEASE: dot-separated identifiers of [0-9A-Za-z-]; numeric identifiers have no leading zeros; identifiers never empty.
  // BUILD: dot-separated non-empty identifiers of [0-9A-Za-z-].
  // A leading v, spaces, or anything else is invalid.

  const regex = /^([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)\.([0]|[1-9][0-9]*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
  const match = v.match(regex);
  if (!match) {
    throw new SyntaxError('Invalid semver version: ' + v);
