{"action":"write_file","path":"semver.test.js","content":"'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const { compareSemver } = require('./semver');

test('compares release versions numerically', () => {
  assert.equal(compareSemver('1.2.3', '1.2.4'), -1);
  assert.equal(compareSemver('2.0.0', '1.9.9'), 1);
  assert.equal(compareSemver('1.10.0', '1.9.0'), 1);
  assert.equal(compareSemver('1.0.0', '1.0.0'), 0);
});

test('compares versions with large numbers accurately', () => {
  assert.equal(compareSemver('1.2.3', '1.2.10'), -1);
  assert.equal(compareSemver('99999999999999999999.0.0', '100000000000000000000.0.0'), -1);
});

test('compares pre-release versions', () => {
  assert.equal(compareSemver('1.0.0-alpha', '1.0.0'), -1);
  assert.equal(compareSemver('1.0.0', '1.0.0-alpha'), 1);
  assert.equal(compareSemver('1.0.0-alpha', '1.0.0-alpha.1'), -1);
  assert.equal(compareSemver('1.0.0-alpha.1', '1.0.0-alpha.beta'), -1);
  assert.equal(compareSemver('1.0.0-beta', '1.0.0-alpha.beta'), 1);
  assert.equal(compareSemver('1.0.0-beta.2', '1.0.0-beta.11'), -1);
  assert.equal(compareSemver('1.0.0-rc.1', '1.0.0-rc.1'), 0);
});

test('ignores build metadata', () => {
  assert.equal(compareSemver('1.0.0+build.1', '1.0.0+build.2'), 0);
  assert.equal(compareSemver('1.0.0-alpha+build.1', '1.0.0-alpha+build.2'), 0);
});

test('throws TypeError on non-string input', () => {
  assert.throws(() => compareSemver(123, '1.0.0'), TypeError);
  assert.throws(() => compareSemver('1.0.0', null), TypeError);
});

test('throws SyntaxError on invalid version string', () => {
  assert.throws(() => compareSemver('v1.0.0', '1.0.0'), SyntaxError);
  assert.throws(() => compareSemver('1.0', '1.0.0'), SyntaxError);
  assert.throws(() => compareSemver('1.0.0.0', '1.0.0'), SyntaxError);
  assert.throws(() => compareSemver('01.0.0', '1.0.0'), SyntaxError);
  assert.throws(() => compareSemver('1.0.0-01', '1.0.0'), SyntaxError);
});
